(function (n) {
    
    n.module('mobileOverlap', []);
})(window.angular),
    (function (n) {
        
        const t = function (n, t, i) {
            const r = this;
            r.stayOnDesktop = function () {
                t.remove('ForcedMobile');
                t.put('ForcedDesktop', 'true');
                i.remove();
            };
            r.goToMobile = function () {
                t.put('ForcedMobile', 'true');
                t.remove('ForcedDesktop');
                window.location = n.absUrl();
            };
            t.get('ForcedDesktop') || t.get('ForcedMobile') || t.put('ForcedDesktop', 'true');
        };
        n.module('mobileOverlap').controller('mobileOverlapCtrl', t);
        t.$inject = ['$location', '$cookies', '$element'];
    })(window.angular);
